func:
// Clear previous partial reads
flow.set("tefs_part_grid", undefined);
flow.set("tefs_part_battery", undefined);
flow.set("tefs_part_load", undefined);
flow.set("tefs_part_pv", undefined);
flow.set("tefs_part_generator", undefined);

// Preserve RPC context if present
const isRpc = msg.isRpcRequest === true;
if (isRpc) {
    flow.set("tefs_rpc_context", {
        requestId: msg.rpcRequestId,
        responseTopic: msg.rpcResponseTopic
    });
} else {
    flow.set("tefs_rpc_context", undefined);
}

return msg;

// Read registers 522-525: Grid import + export
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 522,
    quantity: 4
};
return msg;

// Read registers 516-519: Battery charge + discharge
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 516,
    quantity: 4
};
return msg;

// Read registers 527-528: Load total energy
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 527,
    quantity: 2
};
return msg;

// Read registers 534-535: PV total energy (reserved)
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 534,
    quantity: 2
};
return msg;

// Read registers 537-538: Generator total energy
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 537,
    quantity: 2
};
return msg;

const data = msg.payload;
const address = msg.modbusRequest?.address;

// Helper: u32 from two words
function u32(low, high) {
    return ((high & 0xFFFF) << 16) | (low & 0xFFFF);
}

// Determine which part this is
if (address === 522) {
    // Grid 522-525
    const gridImportLow = data[0] || 0;   // 522
    const gridImportHigh = data[1] || 0;  // 523
    const gridExportLow = data[2] || 0;   // 524
    const gridExportHigh = data[3] || 0;  // 525

    const gridImport = u32(gridImportLow, gridImportHigh);
    const gridExport = u32(gridExportLow, gridExportHigh);

    flow.set("tefs_part_grid", {
        gridImport, gridExport
    });

} else if (address === 516) {
    // Battery 516-519
    const battChargeLow = data[0] || 0;     // 516
    const battChargeHigh = data[1] || 0;    // 517
    const battDischargeLow = data[2] || 0;  // 518
    const battDischargeHigh = data[3] || 0; // 519

    const battCharge = u32(battChargeLow, battChargeHigh);
    const battDischarge = u32(battDischargeLow, battDischargeHigh);

    flow.set("tefs_part_battery", {
        battCharge, battDischarge
    });

} else if (address === 527) {
    // Load 527-528
    const loadLow = data[0] || 0;   // 527
    const loadHigh = data[1] || 0;  // 528

    const loadTotal = u32(loadLow, loadHigh);

    flow.set("tefs_part_load", loadTotal);

} else if (address === 534) {
    // PV 534-535 (reserved)
    const pvLow = data[0] || 0;   // 534
    const pvHigh = data[1] || 0;  // 535

    const pvTotal = u32(pvLow, pvHigh);

    flow.set("tefs_part_pv", pvTotal);

} else if (address === 537) {
    // Generator 537-538
    const genLow = data[0] || 0;   // 537
    const genHigh = data[1] || 0;  // 538

    const genTotal = u32(genLow, genHigh);

    flow.set("tefs_part_generator", genTotal);
}

// Check if all parts are ready
const gridPart = flow.get("tefs_part_grid");
const batteryPart = flow.get("tefs_part_battery");
const loadTotal = flow.get("tefs_part_load");
const pvTotal = flow.get("tefs_part_pv");
const genTotal = flow.get("tefs_part_generator");

if (!gridPart || !batteryPart || loadTotal === undefined || pvTotal === undefined || genTotal === undefined) {
    return null;  // Wait for all parts
}

// All parts ready - assemble payload
const telemetry = {
    timestampUtc: new Date().toISOString(),
    version: 1,
    deviceId: "loftty-inverter",

    grid: {
        importTotalEnergyKWh: Math.round((gridPart.gridImport * 0.1) * 10) / 10,
        exportTotalEnergyKWh: Math.round((gridPart.gridExport * 0.1) * 10) / 10
    },

    pv: {
        totalEnergyKWh: pvTotal === 0 ? null : Math.round((pvTotal * 0.1) * 10) / 10,
        mppt: [
            { id: 1, totalEnergyKWh: null },  // Bu inverterde yok
            { id: 2, totalEnergyKWh: null },  // Bu inverterde yok
            { id: 3, totalEnergyKWh: null },  // Bu inverterde yok
            { id: 4, totalEnergyKWh: null }   // Bu inverterde yok
        ]
    },

    load: {
        totalEnergyKWh: Math.round((loadTotal * 0.1) * 10) / 10
    },

    battery: {
        totalChargeEnergyKWh: Math.round((batteryPart.battCharge * 0.1) * 10) / 10,
        totalDischargeEnergyKWh: Math.round((batteryPart.battDischarge * 0.1) * 10) / 10
    },

    generator: {
        totalEnergyKWh: Math.round((genTotal * 0.1) * 10) / 10
    }
};

// Clear flow context
flow.set("tefs_part_grid", undefined);
flow.set("tefs_part_battery", undefined);
flow.set("tefs_part_load", undefined);
flow.set("tefs_part_pv", undefined);
flow.set("tefs_part_generator", undefined);

// Check if RPC
const rpcContext = flow.get("tefs_rpc_context");
if (rpcContext) {
    msg.topic = rpcContext.responseTopic;
    msg.payload = telemetry;
    flow.set("tefs_rpc_context", undefined);
    return [msg, null];  // Send to RPC output only
} else {
    msg.payload = telemetry;
    return [null, msg];  // Send to telemetry output only
}
